1	// Host API 1.0 gives a panel no way to ask its worker for anything. A panel may show a notification, and
2	// Orca appends each one to its plugin audit log as `titleChars=<length>`. So the panel's refresh button
3	// shows a notification whose title length no worker notification uses, and the worker watches the log.
4	import { unwatchFile, watchFile } from 'node:fs'
5	import { open, stat } from 'node:fs/promises'
6	import { win32 } from 'node:path'
7	import { desktopEnv } from './process.mjs'
8	
9	// panel/template.html shows this exact title; test/refresh-requests.test.mjs keeps the two in step.
10	export const REFRESH_REQUEST_TITLE = 'Entire: refreshing the panel'
11	
12	// Orca's userData on Windows. Verified there only.
13	export function auditLogPath(env = desktopEnv(), platform = process.platform) {
14	  return platform === 'win32' && env.APPDATA ? win32.join(env.APPDATA, 'orca', 'plugins-data', 'audit.log') : null
15	}
16	
17	export function hasRefreshRequest(lines, actor) {
18	  return lines.some((line) => {
19	    try {
20	      const entry = JSON.parse(line)
21	      return (
22	        entry.actor === actor &&
23	        entry.method === 'notifications.show' &&
24	        entry.outcome === 'ok' &&
25	        entry.summary === `titleChars=${REFRESH_REQUEST_TITLE.length}`
26	      )
27	    } catch {
28	      return false
29	    }
30	  })
31	}
32	
33	// Reads only what Orca appends after the worker starts, and starts over when Orca rotates the log.
34	export function watchRefreshRequests(path, actor, onRequest, { intervalMs = 1000 } = {}) {
35	  let offset = null
36	  let reading = false
37	  const check = async () => {
38	    if (reading) return
39	    reading = true
40	    try {
41	      const { size } = await stat(path)
42	      if (offset === null) offset = size
43	      if (size < offset) offset = 0
44	      if (size > offset) {
45	        const file = await open(path, 'r')
46	        try {
47	          const { buffer, bytesRead } = await file.read({ buffer: Buffer.alloc(size - offset), position: offset })
48	          // Leave a line Orca is still writing for the next check.
49	          const end = buffer.subarray(0, bytesRead).lastIndexOf(0x0a) + 1
50	          offset += end
51	          if (hasRefreshRequest(buffer.toString('utf8', 0, end).split('\n'), actor)) onRequest()
52	        } finally {
53	          await file.close()
54	        }
55	      }
56	    } catch {
57	      // No log yet, or Orca is mid-rotation: the next check tries again.
58	    } finally {
59	      reading = false
60	    }
61	  }
62	  check()
63	  // Orca decides how long a worker lives; the watcher never keeps one running.
64	  watchFile(path, { interval: intervalMs }, check).unref()
65	  return { dispose: () => unwatchFile(path, check) }
66	}
