20	export function createFocusTracker({ now = Date.now } = {}) {
21	  const readAt = new Map()
22	  let focused = null
23	
24	  function markRead(key, at = now()) {
25	    if (!key) return
26	    readAt.delete(key)
27	    readAt.set(key, at)
28	    if (readAt.size > MAX_KEPT) readAt.delete(readAt.keys().next().value)
29	  }
