35	    // On a switch, what counts is the panel's own entry, read by shownAt (its time in ms, or null):
36	    // the worker's last read may have been for another branch, or skipped its unchanged write.
37	    dueRead(key, { shownAt = () => null } = {}) {
38	      const switched = key !== focused
39	      focused = key
40	      if (!key) return null
41	      if (switched) {
42	        const at = shownAt()
43	        if (at !== null && now() - at < SWITCH_FRESH_MS) {
44	          // The timer counts from the shown data's read.
45	          markRead(key, at)
46	          return null
47	        }
48	      } else if (readAt.has(key) && now() - readAt.get(key) < AUTO_REFRESH_MS) {
49	        return null
50	      }
51	      markRead(key)
52	      return switched ? 'switch' : 'timer'
53	    }
54	  }
