            })
            .forEach(function (change) {
              add(body, row(el('span', 'mark', '⎇'), el('div', 'clip', change.repository + ' · ' + change.branch), el('div', 'meta clip', words(change.status || ''))))
            })
          return body
        }

        function checkpoints(list) {
          if (!list.length) return el('div', 'empty', 'No checkpoints on this branch yet.')
          var body = el('div')
          list.forEach(function (checkpoint) {
            var id = String(checkpoint.checkpoint_id || '')
            var meta = add(el('div', 'meta clip'), document.createTextNode([checkpoint.agent, ago(checkpoint.date)].filter(Boolean).join(' · ') + ' · '), el('span', 'mono', id.slice(0, 8)))
            add(body, titled(row(null, el('div', 'clip', checkpoint.message || '(no message)'), meta), (checkpoint.message || '') + '\n' + id))
          })
          return body
        }

        function connection(entry) {
          var body = el('div')
          var workspace = entry.workspace
          if (workspace.where) add(body, row(el('span', 'mark ok', '✓'), el('div', 'clip', 'Workspace'), el('div', 'meta clip', 'found via ' + workspace.via)))
          ;(entry.steps || []).forEach(function (s) {
            var tone = s.ok ? 'ok' : s.optional ? '' : 'bad'
            var mark = el('span', 'mark ' + tone, s.ok ? '✓' : s.optional ? '–' : '✕')
            add(body, titled(row(mark, el('div', 'clip', s.label), el('div', 'meta clip', s.text), s.ok ? el('span', 'end', s.ms + ' ms') : null), s.text))
          })
          return body
        }

        // Why a step's data is missing: an error, or (optional) out of the worker's reach, such as a
        // paired server's checkout without SSH.
        function unread(s) {
          if (!s) return el('div', 'empty bad')
          if (!s.optional) return el('div', 'empty bad', s.text)
          return el('div', 'empty', sentence(s.text) + '.')
        }

        function blank(title, text) {
          return add(el('div', 'blank'), el('strong', null, title), el('div', 'muted', text))
        }

        function footer() {
          return add(
            el('footer'),
            document.createTextNode('Checks Entire when you switch here, when an agent finishes and every 5 minutes. To check now, use ↻ or '),
            el('b', null, 'Entire: Refresh panel'),
            document.createTextNode('.')
          )
        }

        function rerender() {
          shown = null
          render(last.context, last.error)
        }

        function render(context, error) {
          last = { context: context, error: error }
          var entry = context ? findEntry(context) : null
          noteSwitch(context, entry)
          var signature = JSON.stringify([context, entry && entry.at, error && error.code, refreshing, refreshHint, checkingSince, Math.floor(Date.now() / 60000)])
          if (signature === shown) return
          shown = signature
          root.textContent = ''

          if (error) return add(root, blank("Can't read the workspace", error.code + ': ' + error.message), footer())
          if (!context) return add(root, blank('No workspace focused', 'Focus a workspace to see its Entire data.'), footer())
          add(root, header(context, entry))
          if (refreshHint) add(root, el('div', 'notice', refreshHint))
          if (!entry) {
            // Nothing written at all means the worker can't write here; otherwise this workspace is new to it.
            return add(
              root,
              DATA
                ? blank('Reading Entire for this workspace…', 'This takes a few seconds after you switch here. If nothing shows, use ↻.')
                : blank('No Entire data yet', 'The panel fills in only when Orca runs this plugin from a Development folder (Settings → Plugins → ⋯ → Development folders).'),
              footer()
            )
          }
          var status = entry.data.status
          if (status) add(root, chips(status))
          notices(entry).forEach(function (notice) {
            add(root, notice)
          })
          if (!entry.steps.length) return add(root, footer())

          var active = (status && status.active_sessions) || []
          if (active.length) add(root, section('sessions', 'Sessions', String(active.length), sessions(status), true))
          else if (!status) add(root, unread(step(entry, 'status')))
          var value = entry.data.trail
          add(root, section('trail', value && value.number ? 'Trail #' + value.number : 'Trail', trailBadge(value), trail(entry), true))
          var list = entry.data.checkpoints
          add(root, section('checkpoints', 'Checkpoints', list ? String(list.length) : '', list ? checkpoints(list) : unread(step(entry, 'checkpoints')), false))
          var bad = failing(entry)
          add(root, section('connection', 'Connection', el('span', 'count ' + (bad ? 'bad' : 'ok'), bad ? 'Problem' : 'OK'), connection(entry), bad), footer())
        }

        // A switch while this panel is up means the worker is about to read the new workspace, unless its
        // data is fresh. The rewrite remounts the panel, which ends the check; the first render after a
        // mount is no switch.
        function noteSwitch(context, entry) {
          var key = context
            ? JSON.stringify([
                context.displayName,
                context.branch,
                context.terminals
                  .map(function (terminal) {
                    return terminal.id
                  })
                  .sort()
              ])
            : null
          if (focusedKey !== null && key !== focusedKey) {
            var stale = !entry || !(Date.now() - Date.parse(entry.at) < SWITCH_FRESH_MS)
            checkingSince = key && stale ? Date.now() : null
          }
          focusedKey = key
          if (checkingSince !== null && Date.now() - checkingSince > CHECK_WAIT_MS) checkingSince = null
        }

        // Keep this the same as findShown in src/worker/panel.mjs.
        function findEntry(context) {
          var list = (DATA && DATA.workspaces) || []
          var ids = context.terminals.map(function (terminal) {
            return terminal.id
          })
          // A workspace keeps its terminals when it switches branch, so a snapshot from the old branch
          // shares them too: the branch has to match as well.
          var byTerminal = list.filter(function (entry) {
            return (
              entry.workspace.branch === context.branch &&
              entry.workspace.terminals.some(function (id) {
                return ids.indexOf(id) >= 0
              })
            )
          })[0]
          if (byTerminal) return byTerminal
          // Many repos share a name and branch such as main/main. Fall back on them only when terminals
          // can't tell the workspaces apart and exactly one entry matches.
          var byName = list.filter(function (entry) {
            var contradicted = ids.length > 0 && entry.workspace.terminals.length > 0
            return !contradicted && entry.workspace.name === context.displayName && entry.workspace.branch === context.branch
          })
          return byName.length === 1 ? byName[0] : null
        }

        // No event tells a panel that focus moved, so ask which workspace is focused every few seconds.
        function tick() {
          if (!orca.host.has('workspace.readContext')) {
            render(null, { code: 'unknown_method', message: 'this Orca has no workspace.readContext' })
            return
          }
          orca.host.call('workspace.readContext', {}).then(
            function (context) {
              render(context, null)
            },
            function (error) {
              render(null, error)
            }
          )
        }

        tick()
        setInterval(tick, 2000)
      })()
    </script>
  </body>
