import { PLUGIN_PANEL_REQUEST_MAX_TIMEOUT_MS } from '../workers/plugin-panel-bridge-protocol'
 * Part of the frame shell's IIFE (plugin-panel-shell.ts), after `orca` exists: `orca.plugin`
