  // signal; Entire's own timeouts bound it.
  function readNow() {
    reading ??= collect().then(add).finally(() => {
      reading = null
    })
    return reading
  }

  async function shown() {
    const context = await readContext()
    return context ? findShown(data, context) : null
  }

