// workspace.changed tells the panel when focus moves or terminals change, but not when the focused
// workspace checks out another branch, so a slow poll catches that.
function tick() {
  if (!orca.host.has('workspace.readContext')) {
    render(null, { code: 'unknown_method', message: 'this Orca has no workspace.readContext' })
    return
  }
  orca.host.call('workspace.readContext', {}).then(
    function (context) {
      render(context, null)
    },
    function (error) {
      render(null, error)
    }
  )
}

if (orca.plugin) orca.plugin.on('entire.changed', fetchData)
// Each new subscriber first gets the current context, so this also renders the first view.
if (orca.api.minor >= 2) {
  orca.on('workspace.changed', function (event) {
    render(event.context, null)
  })
} else {
  tick()
}
