function refreshButton() {
  var busy = reads > 0
  var button = titled(el('button', 'refresh' + (busy ? ' spinning' : '')), busy ? 'Reading Entire…' : 'Refresh')
  button.type = 'button'
  button.setAttribute('aria-label', 'Refresh')
  button.disabled = refreshing
  button.appendChild(icon(['M21 12a9 9 0 1 1-9-9c2.52 0 4.93 1 6.74 2.74L21 8', 'M21 3v5h-5']))
  button.addEventListener('click', function () {
    ask(0, true)
  })
  return button
}

// Asks the worker for its data, reading Entire first unless the focused workspace's entry is
// younger than maxAgeMs (0 always reads). Orca starts the worker if it isn't running.
function ask(maxAgeMs, manual) {
  if (!orca.host.has('plugin.request')) {
    readError = { code: 'unknown_method', message: 'this Orca has no plugin.request. Entire for Orca needs Orca 1.4.246 or later.' }
    return rerender()
  }
  reads++
  if (manual) refreshing = true
  rerender()
  orca.plugin
    .request('entire.read', { maxAgeMs: maxAgeMs }, { timeoutMs: READ_TIMEOUT_MS })
    .then(
      function (data) {
        DATA = data
        readError = null
      },
      function (error) {
        readError = error
      }
    )
    .then(function () {
      reads--
      if (manual) refreshing = false
      rerender()
    })
}

// The worker posts entire.changed after a read nobody here asked for: a command, or an agent
// finishing. Its data comes back through a request, since a post carries at most 256 KiB.
function fetchData() {
  orca.plugin.request('entire.data', {}).then(
    function (data) {
      DATA = data
      rerender()
    },
    function () {}
  )
}

function header(context, entry) {
  var heading = add(el('div', 'heading'), el('span', 'dot ' + (entry ? health(entry) : '')), el('strong', 'clip', context.displayName))
  if (reads > 0) add(heading, el('span', 'when muted', 'Checking…'))

